hints.text:
Una cuenta de ahorro empieza con un saldo y no puede descubrirse. Se quiere saber en qué operación se descubre por primera vez.

function primerDescubierto(saldo, operaciones) {
  for (let i = 0; i < operaciones.length; i++) {
    saldo += operaciones[i];
    if (saldo < 0) {
      return i;
    }
  }
  return -1;
}
